  "claims": [
    {
      "claim": "The query structure matches moclobemide; human single-dose records for moclobemide show rapid oral absorption (Tmax 1.44 h in normal renal function and 1.46 h in renally impaired subjects), consistent with oral absorption.",
      "card_ids": ["C42", "C43"]
    },
    {
      "claim": "A structurally similar para-substituted benzamide, sematilide, has absolute oral bioavailability of 47-59% in humans across multiple studies (0.47 ± 0.15, 0.48 ± 0.16, 58-59%, and 47%), directly supporting F >= 20%.",
      "card_ids": ["C01", "C10", "C20", "C24", "C37"]
    },
    {
      "claim": "Morpholine-containing reference drugs have measured human F values well above 20%: molsidomine 44-59% and linezolid ~93-100%; bepotastine, a related small molecule, is >70-80%.",
      "card_ids": ["C16", "C17", "C19", "C18", "C40", "C11"]
    },
    {
      "claim": "L4 fraction-absorbed records for small-molecule analogs show high absorption (levocetirizine ≥85%, NAPA 87-92%, isoniazid 97-99%, bepotastine >85%, rivaroxaban 80-100%), supporting that absorption is not the limiting step.",
      "card_ids": ["C53", "C54", "C55", "C56", "C57", "C59", "C60", "C61", "C62", "C64"]
    },
    {
      "claim": "L5 bidirectional permeability records for morpholine-containing and related analogs show high A-B permeability with efflux ratios near unity or below (SUVN-G3031 0.81, compound 20 0.5, compound 5v 1.0, fexofenadine dispersion 1.10, rivaroxaban weak efflux), indicating gut-wall efflux is unlikely to reduce F below threshold.",
      "card_ids": ["C65", "C66", "C67", "C74", "C75"]
    },
    {
      "claim": "The only sub-20% measured F among supplied references is linezolid in mice (18.4%, C35), which is species-specific and contradicted by human linezolid F ~93-100% (C40, C19, C18); it does not provide affirmative low-F evidence for the query.",
      "card_ids": ["C35", "C40", "C19", "C18"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C65", "C66", "C67", "C68", "C69", "C70", "C71", "C72", "C73", "C74", "C75", "C76"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself in the supplied records.",
    "No modified-release formulation-specific bioavailability data for the query or a close analog; modified release may alter absorption kinetics, but no evidence indicates F < 20%.",
    "First-pass/intestinal metabolism of the query is not directly quantified; L5 provides permeability/efflux but no direct gut-wall metabolism measurement.",
    "L5 records are for other molecules; duplicate cards (C65/C70/C73, C66/C68/C69, C67/C72, C71/C76) are counted once and are not independent votes.",
    "Some supporting records are from non-human species (mouse, rat, dog) and are used only as context.",
    "C58 (suppository dissolution) and C63 (hippuric acid rat intestinal absorption) are not directly applicable to oral F."
  ],
  "decision_summary": "Predicted high (F >= 20%) with moderate confidence. The query (moclobemide) has a close measured analog sematilide with human F 47-59%, and morpholine/amide references have F 44-100%; L3 oral exposure, L4 high fraction-absorbed, and L5 low-efflux/high-permeability records all support absorption. The only sub-20% value (linezolid in mice, 18.4%) is species-specific and not transferable. Modified-release formulation adds uncertainty but no affirmative low-F evidence."
}

